// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    createSeededRepository,
    deleteRepository,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId
} = require('./workbench-test-helpers.js');

// The page holds still while it works: a running query keeps the results area as tall as it was and shows grey
// placeholder rows where the results will be, and the repository switcher slides the page aside instead of narrowing it.
const REPOSITORY_ID = uniqueRepositoryId('steady-layout');
const VIEWPORT = { width: 1399, height: 652 };
const QUERY = 'SELECT ?s WHERE { VALUES ?s { ' + Array.from({ length: 8 }, (_, i) => `"value ${i}"`).join(' ') + ' } }';

test.beforeAll(async ({ request }) => {
    await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID, { graphs: [], label: 'Steady layout' });
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

async function openQueryPage(page) {
    await page.setViewportSize(VIEWPORT);
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
    await page.locator('.CodeMirror').waitFor({ state: 'visible' });
    await page.evaluate((query) => document.querySelector('.CodeMirror').CodeMirror.setValue(query), QUERY);
}

/** Holds the next query execution until the returned function is called. */
async function holdNextExecution(page) {
    let release;
    const released = new Promise((resolve) => { release = resolve; });
    let held = false;
    await page.route(`**/rdf4j-workbench/repositories/${REPOSITORY_ID}/query**`, async (route) => {
        if (!held && route.request().method() === 'POST' && (route.request().postData() || '').includes('action=exec')) {
            held = true;
            await released;
        }
        await route.continue();
    });
    return () => release();
}

/** Execute as the button does, without Playwright scrolling the button into view first. */
async function execute(page) {
    await page.evaluate(() => document.getElementById('exec').click());
}

async function resultsComplete(page) {
    await expect(page.locator('#query-results .query-result-status')).toContainText('complete');
}

test('running a query again keeps the results area\'s height and the scroll position', async ({ page }) => {
    await openQueryPage(page);
    await execute(page);
    await resultsComplete(page);
    await expect(page.locator('#query-results tbody tr')).toHaveCount(8);
    await page.waitForTimeout(600);
    const scrollTop = await page.evaluate(() => document.scrollingElement.scrollTop);
    expect(scrollTop).toBeGreaterThan(0);
    const height = await page.locator('#query-results').evaluate((results) => results.getBoundingClientRect().height);
    await page.evaluate(() => {
        window.__scrollPositions = [];
        window.addEventListener('scroll', () => window.__scrollPositions.push(document.scrollingElement.scrollTop));
    });

    const release = await holdNextExecution(page);
    await execute(page);
    const skeleton = page.locator('#query-results .query-result-skeleton');
    await expect(skeleton).toBeVisible();
    await expect(page.locator('#query-results tbody tr').first()).toBeHidden();
    const pendingHeight = await page.locator('#query-results').evaluate((results) => results.getBoundingClientRect().height);
    expect(Math.abs(pendingHeight - height)).toBeLessThan(1);
    // The grey rows fill the area down to where the results ended.
    const fill = await page.locator('#query-results').evaluate((results) => {
        const skeleton = results.querySelector('.query-result-skeleton');
        return results.getBoundingClientRect().bottom - skeleton.getBoundingClientRect().bottom;
    });
    expect(fill).toBeLessThan(40);
    expect(await page.evaluate(() => document.scrollingElement.scrollTop)).toBe(scrollTop);

    release();
    await resultsComplete(page);
    await expect(skeleton).toBeHidden();
    await expect(page.locator('#query-results tbody tr')).toHaveCount(8);
    await page.waitForTimeout(600);
    expect(await page.evaluate(() => document.scrollingElement.scrollTop)).toBe(scrollTop);
    expect(await page.evaluate(() => window.__scrollPositions.filter((top) => top !== window.scrollY))).toEqual([]);
});

test('the first run shows placeholder rows where the results will be', async ({ page }) => {
    await openQueryPage(page);
    const release = await holdNextExecution(page);
    await execute(page);
    const skeleton = page.locator('#query-results .query-result-skeleton');
    await expect(skeleton).toBeVisible();
    expect(await skeleton.locator('.query-result-skeleton__row').count()).toBeGreaterThan(3);
    const box = await skeleton.boundingBox();
    expect(box && box.height).toBeGreaterThan(150);
    await expect(page.locator('#query-results .query-result-status')).toContainText('Receiving');

    release();
    await resultsComplete(page);
    await expect(skeleton).toBeHidden();
    await expect(page.locator('#query-results tbody tr')).toHaveCount(8);
});

test('the repository switcher slides the page aside instead of narrowing it', async ({ page }) => {
    await openQueryPage(page);
    const geometry = () => page.evaluate(() => {
        const main = document.getElementById('content').getBoundingClientRect();
        const footer = document.getElementById('footer').getBoundingClientRect();
        const rail = document.getElementById('workbench-contextbar').getBoundingClientRect();
        return {
            mainLeft: main.left, mainWidth: main.width, footerLeft: footer.left, footerWidth: footer.width,
            railWidth: rail.width, scrollWidth: document.scrollingElement.scrollWidth, scrollX: window.scrollX
        };
    });
    /** Waits until the sidebar and the page stop moving. */
    const settled = async () => {
        let previous = null;
        await expect.poll(async () => {
            const current = JSON.stringify(await geometry());
            const same = current === previous;
            previous = current;
            return same;
        }, { intervals: [120] }).toBe(true);
        return geometry();
    };
    const closed = await settled();

    await page.locator('#workbench-repository-switcher').click();
    await expect(page.locator('#workbench-repository-switcher')).toHaveAttribute('aria-expanded', 'true');
    const open = await settled();
    expect(open.railWidth).toBeGreaterThan(closed.railWidth + 100);
    expect(Math.abs(open.mainWidth - closed.mainWidth)).toBeLessThan(1);
    expect(Math.abs(open.mainLeft - closed.mainLeft - (open.railWidth - closed.railWidth))).toBeLessThan(1);
    expect(Math.abs(open.footerWidth - closed.footerWidth)).toBeLessThan(1);
    expect(Math.abs(open.footerLeft - open.mainLeft)).toBeLessThan(1);
    // What slides past the right edge is cut off, not scrolled to.
    expect(open.scrollWidth).toBeLessThanOrEqual(VIEWPORT.width);
    expect(open.scrollX).toBe(0);

    await page.keyboard.press('Escape');
    await expect(page.locator('#workbench-repository-switcher')).toHaveAttribute('aria-expanded', 'false');
    const again = await settled();
    expect(Math.abs(again.mainLeft - closed.mainLeft)).toBeLessThan(1);
    expect(Math.abs(again.mainWidth - closed.mainWidth)).toBeLessThan(1);
});
